// (round 128o, DA-G1) Every GPU data transfer that matters, in one table: each GPU→CPU read, and each GPU→GPU copy
// or CPU→GPU upload whose size the source doesn't show to be small. The gate test/unit/transfers.test.ts scans src/
// for `.mapAsync(`, the calls of the read wrappers below, and every `copyBufferToBuffer` / `copyTexture*` /
// `copyBufferToTexture` / `writeBuffer` / `writeTexture`; a site not in this table fails, and so does an entry whose
// site is gone. A copy or upload is exempt only when the call shows its size as a constant of at most SMALL_BYTES (a
// literal, a file constant, a typed array built with a known length), or when it is the staging copy of a read listed
// in the same function.
//
// The design (DESIGN.md §24): "GPU-resident world. Queries are GPU passes. CPU reads are small, async, and only after
// edits or events; nothing reads back per frame." AGENT_RULES §1b (the user: "flag and scrutinize any large data
// readbacks or copies and try to come up with a way to avoid them and to avoid computation when possible"): every
// large read, upload or whole copy is flagged with its bytes, rate and why. So a read every frame or on a timer in
// play, and a large copy or upload every frame or on a timer in play, must say which rule it breaks (`violates`) and
// which BACKLOG row removes it: listed, not blessed.
//
// Adding a transfer (docs/TESTING.md "The transfer gate"):
//   1. Don't, if the consumer can run where the data is (§24, AGENT_RULES §1b). Send main the design note first.
//   2. Run `npx vitest run --project unit transfers`: the failure names the site as `kind file#Class.method` and its line.
//   3. Add an entry with that kind, file and function, how many calls (`n`), what moves and its bytes, why, its rate,
//      whether it runs in play, and for a copy or upload whether it is `small` (every call <= SMALL_BYTES) or `large`.
//      A new read helper others call: mark it `wrapper` with the pattern of its calls, and list each caller as a `via`
//      entry (the caller sets the rate).
//   4. A frame or timed read in play, or a large frame or timed copy or upload in play, needs `violates` and a
//      `backlog` id. Nothing else gets them.
// Nothing imports this file at run time: it is data for the gate and for people.

/** above this a copy or upload is large (AGENT_RULES §1b): 64 KB, the uniform binding limit, ~1 µs at phone bandwidth */
export const SMALL_BYTES = 65536;

/** what moves: a GPU→CPU read (`mapAsync`), a GPU→GPU copy, a CPU→GPU upload */
export type TransferKind = 'read' | 'copy' | 'upload';

/**
 * How often:
 * - `frame`: every frame or sim tick (or as often as the last read allows);
 * - `timed`: on a timer or every N frames/ticks (`every` says how often);
 * - `edit`: after a world edit or an event (a tap, a slide, a region arriving), small and async per §24;
 * - `demand`: a one-off: boot, create, grow, a tool, a bench, a test or debug API;
 * - `via`: a wrapper; its callers' `via` entries carry the rate.
 */
export type TransferRate = 'frame' | 'timed' | 'edit' | 'demand' | 'via';

/**
 * Whether it runs in fortress play (scenes/level/fortress.ts on the atlas level, frame.ts the play frame):
 * - `yes`: by default;
 * - `flag`: only behind a URL flag that turns on a game or engine path (`flag` names it);
 * - `debug`: only behind a measuring flag (perf overlay, hitch HUD, verify), never a player's;
 * - `no`: other levels, viewers, benches, tests.
 */
export type TransferPlay = 'yes' | 'flag' | 'debug' | 'no';

export interface TransferSite {
  /** default `read` */
  kind?: TransferKind;
  /** the file, relative to src/ */
  file: string;
  /** the enclosing named function, as test/support/source-scan.ts `enclosing` names it */
  fn: string;
  /** calls in that function: `mapAsync(` calls, copies, uploads, or for a `via` entry, calls of the wrapper (default 1) */
  n?: number;
  /** a caller of a read wrapper: the wrapper's `file#fn` */
  via?: string;
  /** a read helper: the pattern of its calls in code; each match elsewhere must be a `via` entry */
  wrapper?: RegExp;
  /** for a copy or upload: every call at most SMALL_BYTES, or not */
  size?: 'small' | 'large';
  /** what moves, and about how many bytes */
  what: string;
  /** why it's needed */
  why: string;
  rate: TransferRate;
  /** for `timed`: how often */
  every?: string;
  play: TransferPlay;
  /** for `flag` / `debug`: the URL flag */
  flag?: string;
  /** the design rule it breaks, e.g. '§24 no timed readback in play' */
  violates?: string;
  /** the BACKLOG row that removes or fixes it */
  backlog?: string;
}

const T24 = '§24 no timed readback in play';
const F24 = '§24 no per-frame readback in play';
const S24 = '§24 reads are small and only after edits';

